                           start->get_profiling_info<
                               sycl::info::event_profiling::command_start>()) /
                          1000000.0f));
        elapsed_time += single_call;
    }

    cudaCheck(DPCT_CHECK_ERROR(
        dpct::dpct_free(flush_buffer, dpct::get_in_order_queue())));

    return elapsed_time / repeats;
}

