                     for (int b = 0; b < B; ++b) {
                       for (int t = 0; t < T; ++t) {
                         sum += dout[(std::size_t)b * (std::size_t)T * (std::size_t)OC +
                                     (std::size_t)t * (std::size_t)OC +
                                     (std::size_t)o];
                       }
                     }
